/** Bengali label for a stored thana name, or the name itself when unmapped. */
export function bnThanaName(district: string | undefined, thana: string): string {
  if (district) {
    const scoped = THANA_NAMES_BN[`${district}||${thana}`];
    if (scoped) return scoped;
  }
  return THANA_NAMES_BN[`||${thana}`] ?? THANA_NAMES_BN[thana] ?? thana;
}
